insert into public.site_config (key, value) values ('site_settings', '{"enterpriseName":"«Тазалык»","enterpriseSubName":"Муниципалдык ишканасы","municipalityName":"Айыл өкмөтү","heroKicker":"Айыл өкмөтү · «Тазалык» МИ · 2026","heroTitle":"Таза айыл, тунук суу жана өнүккөн жамаат","heroSubtitle":"«Тазалык» муниципалдык ишканасынын расмий санариптик сервиси. Коммуналдык квитанцияларды үйдөн чыкпай MBank жана башка тиркемелер аркылуу төлөңүз, суу көрсөткүчүн жибериңиз, жайыт билеттерин рәсмийлештириңиз жана техника ижаралаңыз.","heroWaterCardTitle":"Таза ичүүчү суу","heroWaterCardDesc":"Суу эсептегичтин көрсөткүчүн онлайн тапшыруу жана кудуктарды оңдоо.","heroWasteCardTitle":"Калдыктарды башкаруу","heroWasteCardDesc":"Таштанды чыгаруу графиги, сорттоо пункттары жана полигон акысы.","heroPastureCardTitle":"Жайыт пайдалануу","heroPastureCardDesc":"Мал башы калькулятору, жайыт билеттери жана ачык каржылык отчеттор.","heroMachineryCardTitle":"Атайын техника ижарасы","heroMachineryCardDesc":"Экскаватор, КамАЗ, Портер, таза суу түтүктөрүн жана суу кампаларын оңдоо.","waterSectionTitle":"Таза суу менен камсыздоо жана калдыктарды башкаруу","waterSectionSubtitle":"Суу эсептегич (водомер) көрсөткүчүн онлайн тапшыруу, айылдын таштанды чыгаруу графиги жана санитардык эрежелер.","pastureSectionTitle":"Жайыт пайдалануу жана Жайыт комитети","pastureSectionSubtitle":"Мал башы боюнча мыйзамдуу жайыт билетин онлайн рәсмийлештирүү, жайыт сыйымдуулугун көзөмөлдөө жана чогултулган каражаттардын ачык сарпталышы.","machinerySectionTitle":"Экскаватор, оор жана жеңил жүк ташуучу унаалардын ижарасы","machinerySectionSubtitle":"Айыл тургундарына жана уюмдарга ыңгайлуу баада атайын техникалык кызматтар: тажрыйбалуу оператору жана күйүүчү майы менен берилет.","paymentSectionTitle":"Онлайн төлөм борбору","paymentSectionSubtitle":"Үйүңүздүн жеке лицевой эсебин же фамилиясын киргизип карызды текшериңиз, же каалаган коммуналдык кызмат үчүн MBank, Optima24, O!Dengi жана башка банк системалары аркылуу төлөңүз.","reportsSectionTitle":"Ишкананын жылдык отчеттору жана айыл өкмөтүнүн жаңылыктары","reportsSectionSubtitle":"«Тазалык» муниципалдык ишканасынын киреше-чыгашалары, сатып алынган техникалар жана айылдык кеңештин токтомдору боюнча расмий документтер.","dispatcherPhone":"0 (312) 55-01-20","whatsappPhone":"+996 (702) 00-11-22","officeAddress":"Айыл өкмөтүнүн имараты, Ленин көч. 12","workHours":"Дш–Жм 08:30–17:30","bankName":"РСК Банк / Айыл Банк","bankAccount":"1290123456780192","bankBik":"129001","inn":"01204201010045","okpo":"29481023"}'::jsonb) on conflict (key) do nothing;
